import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { Box, TextField, Button, Typography, Grid, Card, CardContent } from '@mui/material';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const navigate = useNavigate();

    // Handle the login function
    const handleLogin = async () => {
        try {
            const response = await fetch('/api/login', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, password }),
            });

            const data = await response.json();

            if (data.token && data.sessionToken) {
                localStorage.setItem('token', data.token);
                localStorage.setItem('sessionToken', data.sessionToken);
                // Redirect after successful login
                navigate('/dashboard');
            }
        } catch (error) {
            console.error('Error during login:', error);
        }
    };

    // Fetch protected data (useEffect is not async directly, but you can call an async function inside it)
    useEffect(() => {
        const fetchProtectedData = async () => {
            const token = localStorage.getItem('token');
            const sessionToken = localStorage.getItem('sessionToken');
            try {
                const response = await fetch('/api/protected', {
                    headers: {
                        Authorization: `Bearer ${token}`,
                        'X-Session-Token': sessionToken,
                    },
                });
                const data = await response.json();
                console.log('Protected data:', data);
            } catch (error) {
                console.error('Error fetching protected data:', error);
            }
        };

        fetchProtectedData();
    }, []); // Empty dependency array to run this once after component mounts

    return (
        <Box>
            <Card>
                <CardContent>
                    <Typography variant="h5">Login</Typography>
                    <TextField
                        label="Username"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                    />
                    <TextField
                        label="Password"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                    />
                    <Button onClick={handleLogin}>Login</Button>
                </CardContent>
            </Card>
        </Box>
    );
};

export default Login;
